class METCredManSalesFormletterProvider extends SalesFormletterProvider
{
    internal CredManICreditControl creditControl_SalesFormLetter;

    private const CredManHoldType HoldType_Credit = CredManHoldType::Credit;

    private Map releaseReasonMap;

}

Method.Source:
[Hookable(false)]
protected boolean checkBlockedLevel()
{
    boolean ret = true;

    if (this.mustCheckBlockedLevel())
    {
        ret = super();
    }

    return ret;
}

private boolean mustCheckBlockedLevel()
{
    boolean ret = true;

    SalesParmUpdate salesParmUpdate = parmUpdate as SalesParmUpdate;

    if (CredManStatusCheckSetup::METexist(HoldType_Credit, this.documentStatus2DocumentStatusCheck(), salesParmUpdate.Proforma))
    {
        ret = false;
    }

    return ret;
}

/// <summary>
/// Should standard credit limit be checked
/// </summary>
/// <returns>True when credit limit should be checked, false otherwise</returns>
/// <remarks>Run standard credit limit checking if applicable and only if the sales order is a call center order</remarks>
[Hookable(false)]
protected boolean mustCheckCreditLimit()
{
    boolean ret = super();

    ret = ret && salesTable.isRetailSale();

    return ret;
}

internal boolean CredMancreditControlCheck()
{
    if (!creditControl_SalesFormLetter)
    {
        creditControl_SalesFormLetter = CredManCreditControl::newFromDocumentStatusCheck(this.documentStatus2DocumentStatusCheck());
    }

    creditControl_SalesFormLetter.parmReleaseReasonMap(releaseReasonMap);
    creditControl_SalesFormLetter.parmSalesTable(salesTable);
    creditControl_SalesFormLetter.parmSalesParmTable(parmTable as SalesParmTable);
    creditControl_SalesFormLetter.parmSalesParmUpdate(parmUpdate as SalesParmUpdate);
    creditControl_SalesFormLetter.parmSalesTotals(this.parmTotals());

    return creditControl_SalesFormLetter.check();
}

internal Map CredManparmReleaseReasonMap(Map _releaseReasonMap = releaseReasonMap)
{
    releaseReasonMap = _releaseReasonMap;
    return releaseReasonMap;
}

public static METCredManSalesFormletterProvider construct()
{
    return new METCredManSalesFormletterProvider();
}
